"""Check the production deployment guard before any Docker operations."""
from pathlib import Path
import subprocess
import unittest

SERVER_SCRIPT = Path(__file__).resolve().parents[4] / "backend/deploy/vps/server.sh"

class DeployConfirmationTest(unittest.TestCase):
    def run_function(self, body):
        return subprocess.run(
            ["bash", "-c", 'source "$1"\n' + body, "deployment-test", str(SERVER_SCRIPT)],
            capture_output=True,
        )

    # Generated by Codex and not thoroughly checked for correctness.
    def test_deploy_requires_confirmation_before_any_deployment_operation(self):
        for arguments in ("", "--unknown", "--local-backup-confirmed extra"):
            with self.subTest(arguments=arguments):
                result = self.run_function('compose() { exit 99; }\ndeploy ' + arguments + '\n')
                self.assertEqual(result.returncode, 1)
                self.assertIn(b"Create and verify a local database backup first", result.stderr)
                self.assertEqual(result.stdout, b"")

    # Generated by Codex and not thoroughly checked for correctness.
    def test_confirmed_deploy_proceeds_to_bundle_checksum_verification(self):
        result = self.run_function('''
# Stop at the first deployment operation; no files, Docker, or services are changed.
sha256sum() { printf 'checksum: %s\\n' "$*"; exit 73; }
deploy --local-backup-confirmed
''')
        self.assertEqual(result.returncode, 73)
        self.assertEqual(result.stdout, b"checksum: --check SHA256SUMS\n")
        self.assertEqual(result.stderr, b"")

    # Generated by Codex and not thoroughly checked for correctness.
    def test_cli_forwards_confirmation_flag_to_deploy(self):
        result = self.run_function('''
# Replace only administrative preflight and the first deployment operation.
# The production CLI still parses and forwards the confirmation argument.
prepare_administrative_command() {
  [[ $# == 1 && $1 == deploy ]] || exit 99
  printf 'preflight: deploy\\n'
}
sha256sum() { printf 'checksum: %s\\n' "$*"; exit 73; }
main deploy --local-backup-confirmed
''')
        self.assertEqual(result.returncode, 73)
        self.assertEqual(result.stdout, b"preflight: deploy\nchecksum: --check SHA256SUMS\n")
        self.assertEqual(result.stderr, b"")
